<?php if(!empty($payments)):?><section class="panel span-2" id="payments"><div class="panel-head"><div><h2>Payment receipts</h2><p>Receipts for payments recorded against your invoices</p></div></div><div class="compact-list"><?php foreach($payments as $payment):?><div class="list-row"><span class="list-icon"><i class="fa-solid fa-receipt"></i></span><span class="list-main"><strong><?= money($payment['amount']) ?></strong><small><?= e($payment['payment_number']) ?> · <?= e($payment['invoice_number']) ?> · <?= e($payment['payment_mode']) ?></small></span><span class="list-date"><?= e(date('d M Y',strtotime($payment['payment_date']))) ?></span><a class="button button-secondary button-sm" href="<?= url('payments/'.$payment['id'].'/receipt?format=pdf') ?>"><i class="fa-solid fa-download"></i> Receipt</a></div><?php endforeach;?></div></section><?php endif;?>
